export interface SessionSeed {
  id: string;
  title: string;
  capacity: number;
}

export interface Enrollment {
  email: string;
  status: 'confirmed';
}

export interface Roster {
  id: string;
  title: string;
  capacity: number;
  enrollments: Enrollment[];
}

export class DeskError extends Error {
  constructor(public readonly code: string, message: string) {
    super(message);
    this.name = 'DeskError';
  }
}

// Email is the company directory's stable identifier for this application.
export function canonicalEmail(value: string): string {
  const email = value.trim().toLowerCase();
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    throw new DeskError('INVALID_EMAIL', 'A directory email is required');
  }
  return email;
}
import { DeskError, type Enrollment, type SessionSeed } from './model.js';

export interface SessionState extends SessionSeed {
  enrollments: Enrollment[];
}

// Owned by one desk instance. Never exposed directly to callers.
export class SessionStore {
  private readonly sessions = new Map<string, SessionState>();

  constructor(seeds: readonly SessionSeed[]) {
    for (const seed of seeds) {
      if (!seed.id || !seed.title || !Number.isInteger(seed.capacity) || seed.capacity < 1) {
        throw new DeskError('INVALID_SESSION', 'Sessions need an id, title and positive capacity');
      }
      if (this.sessions.has(seed.id)) {
        throw new DeskError('DUPLICATE_SESSION', 'Session ids must be unique');
      }
      this.sessions.set(seed.id, { ...seed, enrollments: [] });
    }
  }

  get(id: string): SessionState {
    const session = this.sessions.get(id);
    if (!session) throw new DeskError('NOT_FOUND', 'Unknown training session');
    return session;
  }
}
import { canonicalEmail, DeskError, type Enrollment, type Roster, type SessionSeed } from './model.js';
import { SessionStore } from './store.js';

export class TrainingDesk {
  private readonly store: SessionStore;

  constructor(seeds: readonly SessionSeed[]) {
    this.store = new SessionStore(seeds);
  }

  enroll(sessionId: string, rawEmail: string): Enrollment {
    const session = this.store.get(sessionId);
    const email = canonicalEmail(rawEmail);
    if (session.enrollments.some(entry => entry.email === email)) {
      throw new DeskError('ALREADY_ENROLLED', 'Employee already enrolled');
    }
    if (session.enrollments.length >= session.capacity) {
      throw new DeskError('FULL', 'Session is full');
    }
    const entry: Enrollment = { email, status: 'confirmed' };
    session.enrollments.push(entry);
    return { ...entry };
  }

  cancel(sessionId: string, rawEmail: string): void {
    const session = this.store.get(sessionId);
    const email = canonicalEmail(rawEmail);
    const index = session.enrollments.findIndex(entry => entry.email === email);
    if (index < 0) throw new DeskError('NOT_ENROLLED', 'Employee is not enrolled');
    session.enrollments.splice(index, 1);
  }

  roster(sessionId: string): Roster {
    const session = this.store.get(sessionId);
    return {
      id: session.id,
      title: session.title,
      capacity: session.capacity,
      enrollments: session.enrollments.map(entry => ({ ...entry })),
    };
  }
}
import { TrainingDesk } from './desk.js';
import { DeskError } from './model.js';

export type PortalReply =
  | { ok: true; status: string }
  | { ok: false; code: string };

// The HTTP adapter passes decoded JSON here; this is a real untrusted boundary.
export function submitEnrollment(desk: TrainingDesk, body: unknown): PortalReply {
  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    return { ok: false, code: 'BAD_REQUEST' };
  }
  const input = body as Record<string, unknown>;
  if (typeof input.sessionId !== 'string' || typeof input.email !== 'string') {
    return { ok: false, code: 'BAD_REQUEST' };
  }
  try {
    const enrollment = desk.enroll(input.sessionId, input.email);
    return { ok: true, status: enrollment.status };
  } catch (error) {
    if (error instanceof DeskError) return { ok: false, code: error.code };
    throw error;
  }
}

// Used by the coordinator's daily attendance export.
export function attendanceEmails(desk: TrainingDesk, sessionId: string): string[] {
  return desk.roster(sessionId).enrollments
    .filter(entry => entry.status === 'confirmed')
    .map(entry => entry.email);
}
import test from 'node:test';
import assert from 'node:assert/strict';
import { TrainingDesk } from '../dist/desk.js';
import { submitEnrollment, attendanceEmails } from '../dist/portal.js';
const make = () => new TrainingDesk([{ id: 's', title: 'First aid', capacity: 1 }]);
test('portal validates unknown data and normalizes directory identity', () => {
  const desk = make();
  assert.deepEqual(submitEnrollment(desk, null), { ok: false, code: 'BAD_REQUEST' });
  assert.deepEqual(submitEnrollment(desk, { sessionId: 's', email: ' A@EXAMPLE.COM ' }), { ok: true, status: 'confirmed' });
  assert.deepEqual(attendanceEmails(desk, 's'), ['a@example.com']);
  assert.deepEqual(submitEnrollment(desk, { sessionId: 's', email: 'a@example.com' }), { ok: false, code: 'ALREADY_ENROLLED' });
});
test('capacity and cancellation preserve atomic failures', () => {
  const desk = make();
  desk.enroll('s', 'a@example.com');
  assert.throws(() => desk.enroll('s', 'b@example.com'), { code: 'FULL' });
  assert.throws(() => desk.cancel('s', 'b@example.com'), { code: 'NOT_ENROLLED' });
  assert.equal(desk.roster('s').enrollments.length, 1);
  desk.cancel('s', ' A@example.com ');
  assert.equal(desk.enroll('s', 'b@example.com').status, 'confirmed');
});
test('snapshots and seeds have independent ownership', () => {
  const seeds = [{ id: 's', title: 'First aid', capacity: 1 }];
  const desk = new TrainingDesk(seeds);
  seeds[0].capacity = 9;
  const entry = desk.enroll('s', 'a@example.com');
  entry.email = 'changed@example.com';
  const roster = desk.roster('s');
  roster.enrollments[0].email = 'changed@example.com';
  roster.enrollments.length = 0;
  assert.equal(desk.roster('s').capacity, 1);
  assert.deepEqual(attendanceEmails(desk, 's'), ['a@example.com']);
});
test('configuration and domain errors', () => {
  assert.throws(() => new TrainingDesk([{ id: 's', title: 'x', capacity: 0 }]), { code: 'INVALID_SESSION' });
  const desk = make();
  assert.throws(() => desk.enroll('missing', 'bad'), { code: 'NOT_FOUND' });
  assert.throws(() => desk.enroll('s', 'bad'), { code: 'INVALID_EMAIL' });
  assert.deepEqual(desk.roster('s').enrollments, []);
});
